-- Same-project explicit identity resolution, retained history and optional reasons.
do $$declare provisional eps.candidates;target eps.candidates;old_pool eps.workspace_candidates;new_pool eps.workspace_candidates;old_media uuid;before_target jsonb;resolved jsonb;request jsonb;reason_input jsonb;result jsonb;after_target jsonb;begin
 select * into strict target from eps.candidates where id=current_setting('eps.behavior.candidate')::uuid;
 select * into strict provisional from eps.candidates where facts->'name'='null'::jsonb and archived_at is null and source_kind='scan';
 select * into strict old_pool from eps.workspace_candidates where candidate_id=provisional.id and archived_at is null;
 select * into strict new_pool from eps.workspace_candidates where candidate_id=target.id and archived_at is null;
 old_media:=old_pool.selected_candidate_media_id;
 execute 'set local role authenticated';
 perform public.eps_update_workspace_candidate(old_pool.id,jsonb_build_object('row_version',old_pool.row_version,'availability','Original project availability','internal_notes','Keep provisional participation history'),'lifecycle-provisional-details');
 before_target:=public.eps_get_candidate(target.id);
 request:=jsonb_build_object('row_version',provisional.row_version,'action','link_existing','existing_candidate_id',target.id,'existing_candidate_row_version',target.row_version);
 resolved:=public.eps_resolve_candidate_duplicate(provisional.id,request,'lifecycle-link-same-project');
 perform pg_temp.kernel_assert(public.eps_resolve_candidate_duplicate(provisional.id,request,'lifecycle-link-same-project')=resolved,'same identity choice exact replay');
 after_target:=public.eps_get_candidate(target.id);
 perform pg_temp.kernel_assert(after_target->'facts'=before_target->'facts' and after_target->'review_status'=before_target->'review_status' and after_target->'row_version'=before_target->'row_version','identity link preserves target facts/Reviewed/version');
 perform pg_temp.kernel_assert(public.eps_get_candidate(provisional.id)->'archived'='true' and public.eps_get_candidate(provisional.id)->>'merged_into_candidate_id'=target.id::text,'retained source record exposes explicit canonical link');
 perform pg_temp.kernel_assert(public.eps_find_candidate_duplicates(provisional.id)='[]'::jsonb,'retained linked detail can load optional duplicate endpoint');
 perform pg_temp.kernel_assert(jsonb_array_length(public.eps_get_candidate_media(target.id))=3,'three source recordings retained under explicit canonical profile');
 execute 'set local role postgres';
 perform pg_temp.kernel_assert((select candidate_id=target.id and archived_at is not null and selected_candidate_media_id=old_media and availability='Original project availability' and internal_notes='Keep provisional participation history' from eps.workspace_candidates where id=old_pool.id),'provisional project row archived/rekeyed with source choices/history intact');
 perform pg_temp.kernel_assert((select selected_candidate_media_id=new_pool.selected_candidate_media_id and selected_frame_asset_ids=new_pool.selected_frame_asset_ids and row_version=new_pool.row_version and archived_at is null from eps.workspace_candidates where id=new_pool.id),'existing project row keeps media/frame choices and version');
 perform pg_temp.kernel_assert((select candidate_id=target.id and row_version=2 from eps.candidate_media where id=old_media),'source recording identity rekey increments media concurrency version');
 execute 'set local role authenticated';
 reason_input:=jsonb_build_object('row_version',target.row_version,'reason','No longer recruiting; retain source history');
 result:=public.eps_archive_candidate(target.id,reason_input,'lifecycle-archive-with-reason');
 perform pg_temp.kernel_assert(public.eps_archive_candidate(target.id,reason_input,'lifecycle-archive-with-reason')=result,'archive reason idempotent');
 begin perform public.eps_archive_candidate(target.id,jsonb_set(reason_input,'{reason}','"Different reason"'),'lifecycle-archive-with-reason');raise exception 'EXPECTED_REASON_IDEMPOTENCY_CONFLICT';exception when raise_exception then if sqlerrm<>'IDEMPOTENCY_KEY_REUSED' then raise;end if;end;
 perform pg_temp.kernel_assert(public.eps_get_candidate(target.id)->'archived'='true' and public.eps_get_candidate(target.id)->'facts'=before_target->'facts','archived facts remain readable to casting actor');
 perform pg_temp.kernel_assert(public.eps_find_candidate_duplicates(target.id)='[]'::jsonb,'retained archived detail can load optional duplicate endpoint');
 perform pg_temp.kernel_assert(jsonb_array_length(public.eps_get_candidate_media(target.id))=3,'archived profile originals/frames remain accessible');
 perform pg_temp.kernel_assert(jsonb_array_length(public.eps_search_candidates(jsonb_build_object('q',target.casting_id))->'data')=0,'archive omitted from active library search');
 reason_input:=jsonb_build_object('row_version',new_pool.row_version,'reason','Removed from this project only');
 result:=public.eps_remove_workspace_candidate(new_pool.id,reason_input,'lifecycle-remove-with-reason');
 perform pg_temp.kernel_assert(public.eps_remove_workspace_candidate(new_pool.id,reason_input,'lifecycle-remove-with-reason')=result,'project remove exact replay');
 perform pg_temp.kernel_assert(jsonb_array_length(public.eps_get_candidate_media(target.id))=3,'project removal cannot physically delete shared media');
 execute 'set local role postgres';
 perform pg_temp.kernel_assert((select count(*)=2 from eps.cast_operation_notes where principal_id='7aae0000-0000-4000-8000-000000000001'),'optional archive/remove reasons retained once as private audit context');
 perform pg_temp.kernel_assert((select count(*)=1 from eps.audit_events where principal_id='7aae0000-0000-4000-8000-000000000001' and action='cast.resolve_candidate_duplicate' and resource_id=provisional.id),'explicit identity resolution audit retained');
end $$;
select 'CANDIDATE_RETAINED_HISTORY_EXPLICIT_LINK_AND_REASON_PARITY_PASSED';
